"""Text-to-SQL harness with execution verification and one repair attempt.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str     capped per task: env.max_calls
  env.schema(db_id) -> str
  env.execute(sql, max_rows=20) -> dict          {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str
  env.prompt(name) -> str
  env.config -> dict
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'((?:[^']|'')*)'")
IDENT = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    t = (text or "").strip()
    m = re.search(r"(?is)\b(select|with)\b.*", t)
    if m:
        t = m.group(0)
    return t.rstrip(";").strip()


def _run(env, sql):
    try:
        r = env.execute(sql, max_rows=5)
    except Exception as e:  # pragma: no cover - defensive
        return {"ok": False, "columns": [], "rows": [], "n_rows": 0, "error": str(e)}
    if not isinstance(r, dict):
        return {"ok": False, "columns": [], "rows": [], "n_rows": 0, "error": "no result"}
    return r


def _probe_notes(env, sql):
    """Generic diagnostics: sample real values of columns compared to string literals."""
    lits = [m.group(1) for m in LITERAL.finditer(sql)]
    lits = [l for l in lits if l and not l.replace(".", "").isdigit()]
    if not lits:
        return ""
    cols = set(IDENT.findall(re.sub(r"'(?:[^']|'')*'", " ", sql)))
    notes = []
    seen = set()
    for lit in lits[:3]:
        core = lit.strip("%_ ")
        if len(core) < 3:
            continue
        frag = core.split()[0] if core.split() else core
        for col in sorted(cols):
            if len(col) < 3 or col.lower() in ("select", "from", "where", "like", "and", "or", "not", "join", "on"):
                continue
            key = (col.lower(), frag.lower())
            if key in seen:
                continue
            seen.add(key)
            q = (
                'SELECT DISTINCT "%s" FROM (%s) LIMIT 5' % (col, sql)
            )
            # probing the filtered query yields nothing; probe base tables instead
            q = "SELECT DISTINCT %s FROM %s WHERE %s LIKE '%%%s%%' LIMIT 5"
            # find a table that owns this column via sqlite_master-free trial
            for tbl in _tables(env):
                probe = q % (col, tbl, col, frag.replace("'", "''"))
                r = _run(env, probe)
                if r.get("ok") and r.get("rows"):
                    vals = [str(row[0]) for row in r["rows"]]
                    notes.append("Actual values in %s.%s matching %r: %s" % (tbl, col, frag, vals))
                    break
            if len(notes) >= 3:
                return "\n".join(notes)
    return "\n".join(notes)


def _tables(env):
    r = _run(env, "SELECT name FROM sqlite_master WHERE type='table'")
    if not r.get("ok"):
        return []
    return [row[0] for row in r.get("rows", [])][:20]


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 800)
    schema = env.schema(task["db_id"])
    user = "Database: %s\n\nSchema:\n%s\n\nQuestion: %s" % (task["db_id"], schema, task["question"])
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()[:2000]
    if task.get("hint"):
        user += "\nHint: " + task["hint"]
    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    res = _run(env, sql)
    ok = bool(res.get("ok"))
    nrows = res.get("n_rows", 0) or 0
    if ok and nrows > 0:
        return {"sql": sql}

    feedback = ["Your draft query:", "```sql", sql, "```"]
    if not ok:
        feedback.append("It failed with error: %s" % res.get("error"))
    else:
        feedback.append(
            "It executed but returned 0 rows. The question almost certainly has a non-empty answer, "
            "so something in the query is wrong: a join key/column pairing, the column a literal is "
            "compared against, the exact stored spelling/case of a value, or the direction of a LIKE "
            "pattern (use column LIKE '%text%' when searching for text inside a column)."
        )
        notes = _probe_notes(env, sql)
        if notes:
            feedback.append("Diagnostics from the database:\n" + notes)
    feedback.append(
        "Re-inspect the schema, fix the cause, and return the corrected query in a single ```sql block. "
        "Keep the same output columns unless they were themselves wrong."
    )
    messages = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": "\n".join(feedback)},
    ]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = _run(env, sql2)
    if res2.get("ok") and (res2.get("n_rows", 0) or 0) > 0:
        return {"sql": sql2}
    if res2.get("ok") and not ok:
        return {"sql": sql2}
    return {"sql": sql}

